1	import { Router } from "express";
2	import type { Db } from "@paperclipai/db";
3	import { AGENT_ICON_NAMES } from "@paperclipai/shared";
4	import { forbidden } from "../errors.js";
5	import { listServerAdapters } from "../adapters/index.js";
6	import { agentService } from "../services/agents.js";
7	import { expressHandler } from "../http/express-adapter.js";
8	import type { Handler, RequestCtx } from "../http/types.js";
9	import type { StorageService } from "../storage/types.js";
10	
11	function hasCreatePermission(agent: { role: string; permissions: Record<string, unknown> | null | undefined }) {
12	  if (!agent.permissions || typeof agent.permissions !== "object") return false;
13	  return Boolean((agent.permissions as Record<string, unknown>).canCreateAgents);
14	}
15	
16	function textPlain(body: string): Response {
17	  return new Response(body, { headers: { "content-type": "text/plain; charset=utf-8" } });
18	}
19	
20	function buildHandlers(db: Db) {
21	  const agentsSvc = agentService(db);
22	
23	  async function assertCanRead(ctx: RequestCtx) {
24	    if (ctx.actor?.type === "board") return;
25	    if (ctx.actor?.type !== "agent" || !ctx.actor.agentId) {
26	      throw forbidden("Board or permitted agent authentication required");
27	    }
28	    const actorAgent = await agentsSvc.getById(ctx.actor.agentId);
29	    if (!actorAgent || !hasCreatePermission(actorAgent)) {
30	      throw forbidden("Missing permission to read agent configuration reflection");
31	    }
32	  }
33	
34	  // server/src/routes/llms.ts:28
35	  const getAgentConfigurationIndex: Handler = async (ctx) => {
36	    await assertCanRead(ctx);
37	    const adapters = listServerAdapters().sort((a, b) => a.type.localeCompare(b.type));
38	    const lines = [
39	      "# Paperclip Agent Configuration Index",
40	      "",
41	      "Installed adapters:",
42	      ...adapters.map((adapter) => `- ${adapter.type}: /llms/agent-configuration/${adapter.type}.txt`),
43	      "",
44	      "Related API endpoints:",
45	      "- GET /api/companies/:companyId/agent-configurations",
46	      "- GET /api/agents/:id/configuration",
47	      "- POST /api/companies/:companyId/agent-hires",
48	      "",
49	      "Agent identity references:",
50	      "- GET /llms/agent-icons.txt",
51	      "",
52	      "Notes:",
53	      "- Sensitive values are redacted in configuration read APIs.",
54	      "- New hires may be created in pending_approval state depending on company settings.",
55	      "- Use the paperclip-create-agent skill for end-to-end hiring: adapter reflection, config comparison, instruction source selection, icon choice, desiredSkills, sourceIssueId/sourceIssueIds, and approval follow-up.",
56	      "- Timer heartbeats are opt-in for new hires. Leave runtimeConfig.heartbeat.enabled false unless the role truly needs scheduled work or the user explicitly asked for it.",
57	      "",
58	    ];
59	    return textPlain(lines.join("\n"));
60	  };
61	
62	  // server/src/routes/llms.ts:55
63	  const getAgentIcons: Handler = async (ctx) => {
64	    await assertCanRead(ctx);
65	    const lines = [
66	      "# Paperclip Agent Icon Names",
67	      "",
68	      "Set the `icon` field on hire/create payloads to one of:",
69	      ...AGENT_ICON_NAMES.map((name) => `- ${name}`),
70	      "",
71	      "Example:",
72	      '{ "name": "SearchOps", "role": "researcher", "icon": "search" }',
73	      "",
74	    ];
75	    return textPlain(lines.join("\n"));
76	  };
77	
78	  // server/src/routes/llms.ts:70
79	  const getAdapterConfiguration: Handler = async (ctx) => {
80	    await assertCanRead(ctx);
81	    const adapterType = ctx.param("adapterType") ?? "";
82	    const adapter = listServerAdapters().find((entry) => entry.type === adapterType);
83	    if (!adapter) {
84	      return new Response(`Unknown adapter type: ${adapterType}`, {
85	        status: 404,
86	        headers: { "content-type": "text/plain; charset=utf-8" },
87	      });
88	    }
89	    return textPlain(
90	      adapter.agentConfigurationDoc ??
91	        `# ${adapterType} agent configuration\n\nNo adapter-specific documentation registered.`,
92	    );
93	  };
94	
95	  return { getAgentConfigurationIndex, getAgentIcons, getAdapterConfiguration };
96	}
97	
98	export function llmRoutes(db: Db) {
99	  const router = Router();
100	  const { getAgentConfigurationIndex, getAgentIcons, getAdapterConfiguration } = buildHandlers(db);
101	
102	  const storageSentinel = new Proxy({} as StorageService, {
103	    get(_target, prop) {
104	      throw new Error(`llm handler unexpectedly accessed storage.${String(prop)}`);
105	    },
106	  });
107	  const deps = { db, storage: storageSentinel };
108	
109	  router.get("/llms/agent-configuration.txt", expressHandler(getAgentConfigurationIndex, deps));
110	  router.get("/llms/agent-icons.txt", expressHandler(getAgentIcons, deps));
111	  router.get("/llms/agent-configuration/:adapterType.txt", expressHandler(getAdapterConfiguration, deps));
112	
113	  return router;
114	}
